[
  {
    "text": "Trait boredom and state boredom are empirically distinct constructs, so elevated trait boredom in ADHD does not logically entail altered state boredom dynamics.",
    "topic": "Construct distinction"
  },
  {
    "text": "Performance-based attention control may moderate the effect of ADHD symptoms on state boredom, while trait boredom reflects the cumulative impact of chronic attention deficits.",
    "topic": "Attention control role"
  },
  {
    "text": "A longitudinal design can test whether attention control deficits predict increases in trait boredom over time in adults with ADHD symptoms.",
    "topic": "Longitudinal test"
  },
  {
    "text": "Statistical mediation analysis can determine if attention control deficits fully or partially account for the trait boredom elevation seen in ADHD.",
    "topic": "Mediation hypothesis"
  }
]
